    import logo from './logo.jpg';
    import './Menu.css';
    import { FaSearch, FaShoppingCart, FaChevronDown } from 'react-icons/fa';
    import { useState } from 'react';
    import { useNavigate } from "react-router-dom";

    const Menu = () => {
        const navigate = useNavigate();
        const [dropdownOpen, setDropdownOpen] = useState(false);

        return (
            <nav className="menu">
                <div className="menu-container">
                    <a href="/home" className="logo-link">
                        <img src={logo} alt="Logo" className="logo" />
                    </a>
    
                    <ul className="menu-list">
                        <li className="menu-item"><a href="/about-us">Về chúng tôi</a></li>
                        <li className="menu-item"><a href="/blog">Blog</a></li>

                        <li className="menu-item dropdown"
                            onMouseEnter={() => setDropdownOpen(true)}
                            onMouseLeave={() => setDropdownOpen(false)}>
                            <button className="dropdown-btn">Sản phẩm <FaChevronDown className="dropdown-icon" /></button>
                            {dropdownOpen && (
                                <ul className="dropdown-menu">
                                    <li><a href="/men">Đồ Nam</a></li>
                                    <li><a href="/women">Đồ Nữ</a></li>
                                    <li><a href="/kids">Trẻ Em</a></li>
                                </ul>
                            )}
                        </li>

                        <li className="menu-item"><a href="/new-arrivals">Hàng mới về</a></li>
                    </ul>

                    <div className="menu-actions">
                        <div className="search-wrapper">
                            <input type="text" placeholder="Tìm kiếm..." className="search-input" />
                            <button className="search-button"><FaSearch /></button>
                        </div>

                        <button className="auth-button" onClick={() => navigate("/login")}>Đăng nhập</button>
                        <button className="auth-button" onClick={() => navigate("/register")}>Đăng ký</button>
                        <button className="cart-button" onClick={() => navigate("/giohang")}>
                            <FaShoppingCart />
                        </button>
                    </div>
                </div>
            </nav>
        );
    };

    export default Menu;
